using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Recovery;

internal sealed class WholeSmoothRecoveryDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The original ST37 statement for actual smooth reversible channels and their range bundles.",
        H("Whole smooth recovery"),
        Blocks(Describe.Lean(
            DescribeId.Create("whole-original-st37"),
            DeclarationHandle.Create("D5/S3/Quantum/Recovery/WholeSmoothRecovery.whole_original_ST37"),
            H("The whole original ST37 theorem"),
            StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(
                LibraryNoteRef.Create("D5/L/Quantum/nayaksen2007invertible"),
                LibraryNoteRef.Create("D5/L/Quantum/choijohnstonkribs2009multiplicative")),
            Blocks(
                Paragraph(Text("Let B be an arbitrary compact real smooth manifold, with its original model with corners. Let d, n and k be arbitrary natural numbers with only d > 0 assumed. A smooth family N_x of complex linear matrix channels is completely positive and trace preserving, has a pointwise completely positive trace-preserving left inverse, and satisfies rank(N_x(identity)) = k d. The left inverse is not assumed to vary smoothly. Empty bases, n = 0 and k = 0 retain their original logical scope.")),
                Paragraph(Text("Put Q_x = N_x(identity), P_x = spectralSupport(Q_x), W_x = spectralInverseSqrt(Q_x), and pi_x(T) = W_x N_x(T) W_x. These are the actual spectral functions, with inverse square root zero on the kernel. The theorem proves smoothness of Q, P and W and joint smoothness of pi. It also establishes pi(identity) = P, preservation of adjoints and multiplication, commutation with Q, and N_x(T) = Q_x pi_x(T) for every complex matrix T.")),
                Paragraph(Text("Fix v = 0 in Fin d and set F_x(i,j) = pi_x(e_ij). The explicit decoder uses the matrix-unit Kraus family together with reset Kraus operators single(v,b,1)(identity - P_x). Every Kraus coefficient varies smoothly and the decoder is jointly smooth in x and its matrix input. It is completely positive and trace preserving, recovers every complex T exactly, and recovers after tensoring with the identity at every natural reference dimension. The two coordinate formulas identify it with the matrix-unit trace expression and the corresponding spectral transpose expression.")),
                Paragraph(Text("The support bundle E_x = range(P_x) has complex rank k d. The syndrome bundle F_x = range(F_x(v,v)) has complex rank k. The theorem constructs real smooth prebundles for E, F and the actual canonical complex tensor fibers F_x tensor C^d. It supplies their complex vector-bundle structures, identifies the E and F total-space topologies with their ambient induced topologies, proves the ambient embeddings and their smoothness, and verifies the tensor-chart base sets and action on pure tensors.")),
                Paragraph(Text("A family Theta_x: F_x tensor C^d -> E_x of complex linear isometric equivalences is characterized by Theta_x(w tensor e_i) = F_x(i,v)w. Its inverse has the finite coordinate formula sum_i back_x(y)_i tensor e_i, with back_x(y)_i = F_x(v,i)y in the ambient physical space. The adjoint of Theta is its inverse. The adjoint-composition identities for the two bundle inclusions give the identity on each fiber and the actual ambient projections P_x and F_x(v,v). Both Theta and its inverse are smooth maps of the actual total spaces.")),
                Paragraph(Text("The syndrome endomorphism sigma_x is the restriction of Q_x; sigmaInv_x is the restriction of W_x W_x. Both give smooth total-space maps. The former is positive and has strictly positive real inner product on every nonzero fiber vector, both inverse identities hold, and its complex linear trace is one. The intertwining identity Q_x Theta_x = Theta_x(sigma_x tensor identity) and the channel factorization N_x(T) = U_x(sigma_x tensor T)U_x* hold for all complex T, where U_x is the support inclusion composed with Theta_x.")),
                Paragraph(Text("For the original input-first Choi convention J_x, the theorem proves positivity, rank k, the precise index-swap relation to MatrixMap.choi_matrix, and smoothness of J_x and its actual CFC square root. Reshaping the square-root columns gives the specified redundant Kraus family A_x(mu), with smooth coefficients, exact channel expansion and sum_mu A_x(mu)* A_x(mu) = identity.")),
                Paragraph(Text("The final witness is the actual Stinespring isometry into C^n tensor C^(d n): V_x(u) = sum_mu A_x(mu)u tensor e_mu. The complex Euclidean and tensor norms and inner products are the original ones. Orthogonality of the environment basis and the Kraus normalization prove isometry; the finite tensor sum varies jointly smoothly in x and u. The final coordinate identity reconstructs N_x(T) from the coefficients of this V for every complex T.")),
                Paragraph(Text("The proof reuses the existing pointwise reversible-channel construction and its explicit inverse formula. Actual constant-rank spectral smoothness comes from the Hermitian square-map local inverse and local Gram coordinates. Tensor coefficients in local range-bundle charts prove the global smoothness assertions; no global vector frame, smoothly selected recovery family or extra spectral regularity premise is supplied. The result does not assert ST38, later control statements, or an unresolved external conjecture.")),
                Paragraph(Text("Nayak and Sen establish the finite reversible-channel fixed-ancilla normal form; Choi, Johnston and Kribs supply relevant multiplicative-domain context. The application here specifies actual spectral functions, their smooth parameter dependence, the concrete range and tensor bundles, and the original decoder and redundant Choi-column witnesses. These references do not assert a verbatim external Lean implementation or a new literature priority claim.")),
                Paragraph(Text("The following controlled-interval consequence applies whole_original_ST37, MatrixUnitDyson.constructive_transport, MatrixUnitGenerator.generator_from_real_path, the original MatrixUnitDecoder.weighted_pairing and IptPptSquaredEquivalence.kron_id_apply. The remaining steps are product, linear-map and exponential calculus and matrix/trace normalization. This application has no separate retained theorem or mathematical content credit; its exact check is transient.")),
                Paragraph(Text("For the controlled-interval application, retain the original compact smooth parameter manifold, actual smooth reversible complex channel family, constant rank k d, and d > 0. The physical dimension n and syndrome rank k are arbitrary natural numbers. A real path selects actual spectral data Q=N(identity), P=spectralSupport(Q), W=spectralInverseSqrt(Q), pi(A)=W N(A) W, and F(i,j)=pi(e_ij). The path hypothesis is precisely continuity of these actual matrix units and of their supplied velocities, with the entrywise within derivative equations on [0,T]. For a singleton interval the velocity is tied to a genuine ambient derivative of the same actual path at zero. No transport equation or decoder identity is a path hypothesis.")),
                Paragraph(Text("For every continuous logical Hermitian h_L on the closed interval, and every positive hbar and Delta, K is the computed matrix-unit generator and G is its actual dysonSeries. The logical path V_L is dysonSeries((-i/hbar)h_L), with its initial identity, continuity, two-sided unitarity and logical Schrodinger equation as conclusions. No commutation between h_L at different times is required.")),
                Paragraph(Text("Define exactly H_phys=i hbar K+pi_t(h_L)+Delta(identity-P_t), and V=G[pi_0(V_L)+exp(-i Delta t/hbar)(identity-P_0)]. The conclusions give Hermiticity of H_phys, the initial identity V(0)=identity, continuity and two-sided unitarity of V, and its physical Schrodinger equation as a within derivative at every point of the closed interval. The derivative is specified explicitly; the statement does not use uniqueness of a singleton within derivative.")),
                Paragraph(Text("For every incoming matrix weight R commuting with all initial logical matrix units, with P_0 R=R and trace(F_0(v,v)R)=1, the same transported R_t=G R G* has both support equations, commutes with the whole moving represented algebra, preserves its full trace and syndrome trace, and is positive semidefinite whenever R is. For every complex logical matrix A the physical output is exactly R_t pi_t(V_L A V_L*). These assertions include matrices outside the state cone.")),
                Paragraph(Text("The decoder is the fixed canonical ST37 Kraus construction: decoderKraus(F_t,v), together with the prescribed reset Kraus matrices single(v,b,1)(identity-P_t). Its actual ST37 trace formula and MatrixUnitDecoder.weighted_pairing recover every weighted output. The original decoder_recovers_commutant_weight consumer of weighted_pairing is preserved. No existential replacement channel is used.")),
                Paragraph(Text("At every natural reference dimension q and for every joint complex matrix on Fin d times Fin q, the nested encoding, physical conjugation and this canonical decoder, each tensored with the reference identity, equal logical conjugation tensored with that identity. The proof reads arbitrary reference blocks, including off-diagonal blocks, rather than reducing the input to separable states. Substitution of the actual initial weight Q_0=N_0(identity) gives the same explicit output, its positive transported weight, the exact canonical decoded output and the reference equality for N_0 itself.")),
                Paragraph(Text("The transported syndrome weight is not identified with the preset Q_t. The evolution and all-matrix recovery application is the segment relation required by the finite experiment construction; that construction is not supplied here. The separate geometric norm estimate, closed-loop syndrome factorization, normalization with a distinct failure outcome, and complete finite adaptive protocol with equality of all records remain further mathematical obligations. No control bandwidth, energy, spatial locality, adiabatic approximation or new literature priority is asserted."))),
            DescribeRole.Theorem))));
}
